}

/* ---------- Toast ---------- */
.toast-region {
  position: fixed;
  bottom: 24px; right: 24px;
  display: flex; flex-direction: column; gap: 8px;
  z-index: 100;
  pointer-events: none;
}
.toast {
  background: var(--ink);
  color: #fff;
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: var(--shadow-md);
  font-size: .9375rem;
  pointer-events: auto;
  display: flex; align-items: center; gap: 10px;
  animation: toast-in .2s ease-out;
}
@keyframes toast-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
  }
}

/* ---------- Forced colors ---------- */
@media (forced-colors: active) {
  .btn, .add-to-cart, .icon-btn, .wishlist-btn, .cat-card, .product, .editorial-card, .deal-tile {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .add-to-cart:hover { background: ButtonText; color: ButtonFace; }
  .badge-pill, .countdown-cell { border: 1px solid ButtonBorder; }
  .stars-fill { color: Highlight; }
  a:focus-visible, button:focus-visible, input:focus-visible {
    outline: 3px solid Highlight;
  }
}
