arguments.file_text:
:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --ink: #14110f;
  --ink-2: #3a3530;
  --muted: #6b645d;
  --line: #e6e2dc;
  --line-strong: #1a1714;
  --accent: #c2410c;
  --accent-ink: #ffffff;
  --sale: #b91c1c;
  --ok: #15803d;
  --focus: #1d4ed8;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20,17,15,.06);
  --shadow-md: 0 8px 24px rgba(20,17,15,.08);
  --maxw: 1240px;
  --font: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --serif: "Fraunces", "Iowan Old Style", Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  line-height: 1.5;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; }
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, summary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 8px;
  top: -100px;
  background: var(--ink);
  color: #fff;
  padding: 10px 14px;
  border-radius: 6px;
  z-index: 1000;
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus { top: 8px; }

/* ---------- Layout helpers ---------- */
.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

@media (max-width: 640px) {
  .container { padding: 0 16px; }
}

/* ---------- Announcement bar ---------- */
.announce {
  background: var(--ink);
  color: #fff;
  text-align: center;
  font-size: .875rem;
  padding: 10px 16px;
}
.announce strong { color: #fff; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}
.header-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 24px;
  align-items: center;
  padding: 16px 0;
}
.brand {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.5rem;
  letter-spacing: .02em;
  text-decoration: none;
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.brand-mark {
  width: 32px; height: 32px;
  background: var(--ink);
  color: #fff;
  border-radius: 8px;
  display: grid; place-items: center;
  font-family: var(--serif);
  font-weight: 700;
}

.primary-nav ul {
  display: flex;
  gap: 8px;
  list-style: none;
  margin: 0; padding: 0;
  justify-content: center;
}
.primary-nav a {
  text-decoration: none;
  color: var(--ink-2);
  padding: 8px 12px;
  border-radius: 6px;
  font-weight: 500;
}
.primary-nav a:hover { background: #f1ede6; color: var(--ink); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  appearance: none;
  background: transparent;
  border: 1px solid transparent;
  width: 40px; height: 40px;
  border-radius: 8px;
  display: inline-grid;
  place-items: center;
  cursor: pointer;
  color: var(--ink);
  position: relative;
}
.icon-btn:hover { background: #f1ede6; }
.icon-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: .65rem;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-weight: 700;
  border: 2px solid var(--surface);
}

.menu-toggle { display: none; }

@media (max-width: 880px) {
  .header-row { grid-template-columns: auto 1fr auto; }
  .primary-nav {
    grid-column: 1 / -1;
    order: 3;
    border-top: 1px solid var(--line);
    margin: 0 -24px -16px;
    padding: 8px 16px;
    overflow-x: auto;
  }
  .primary-nav ul { justify-content: flex-start; flex-wrap: nowrap; }
  .primary-nav a { white-space: nowrap; }
}

/* ---------- Hero ---------- */
.hero {
  background: linear-gradient(180deg, #f4efe6 0%, #ece5d6 100%);
  border-bottom: 1px solid var(--line);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 64px 0;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .75rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 600;
  background: rgba(20,17,15,.06);
  padding: 6px 10px;
  border-radius: 999px;
}
.hero h1 {
  font-family: var(--serif);
  font-weight: 600;
  font-size: clamp(2.25rem, 4.5vw, 3.5rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 16px 0 16px;
}
.hero p {
  color: var(--ink-2);
  font-size: 1.0625rem;
  max-width: 52ch;
  margin: 0 0 28px;
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.hero-meta {
  margin-top: 32px;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  color: var(--ink-2);
  font-size: .875rem;
}
.hero-meta div { display: flex; align-items: center; gap: 8px; }

.hero-figure {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: #d9cfbb;
  box-shadow: var(--shadow-md);
}
.hero-figure img { width: 100%; height: 100%; object-fit: cover; }
.hero-tag {
  position: absolute;
  left: 20px; bottom: 20px;
  background: var(--surface);
  padding: 12px 16px;
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  font-size: .875rem;
  display: flex;
  flex-direction: column;
}
.hero-tag strong { color: var(--ink); font-size: 1rem; }
.hero-tag span { color: var(--muted); }

@media (max-width: 880px) {
  .hero-grid { grid-template-columns: 1fr; padding: 40px 0; gap: 32px; }
  .hero-figure { aspect-ratio: 4 / 3; }
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.9375rem;
  padding: 12px 20px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  text-decoration: none;
  transition: background-color .15s ease, border-color .15s ease, color .15s ease;
  white-space: nowrap;
}
.btn-primary {
  background: var(--ink);
  color: #fff;
}
.btn-primary:hover { background: #2a2520; }
.btn-secondary {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-secondary:hover { background: var(--ink); color: #fff; }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line);
}
.btn-ghost:hover { background: var(--surface); border-color: var(--ink); }

.btn[aria-disabled="true"] { opacity: .5; cursor: not-allowed; }

/* ---------- Section ---------- */
section { padding: 72px 0; }
@media (max-width: 640px) { section { padding: 48px 0; } }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: var(--serif);
  font-weight: 600;
  font-size: clamp(1.75rem, 3vw, 2.25rem);
  letter-spacing: -0.01em;
  margin: 8px 0 0;
}
.section-head p {
  color: var(--muted);
  margin: 8px 0 0;
  max-width: 50ch;
}
.section-head .head-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

/* ---------- Category strip ---------- */
.categories {
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  padding: 36px 0;
}
.categories ul {
  list-style: none;
  margin: 0; padding: 0;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
@media (max-width: 880px) {
  .categories ul { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 480px) {
  .categories ul { grid-template-columns: repeat(2, 1fr); }
}
.cat-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  text-decoration: none;
  color: var(--ink);
  background: var(--bg);
  transition: transform .15s ease, border-color .15s ease;
}
.cat-card:hover { transform: translateY(-2px); border-color: var(--ink); }
.cat-icon {
  width: 48px; height: 48px;
  display: grid; place-items: center;
  border-radius: 50%;
  background: #efe9dc;
  color: var(--ink);
}
.cat-name { font-weight: 600; font-size: .9375rem; }
.cat-count { color: var(--muted); font-size: .75rem; }

/* ---------- Products grid ---------- */
.products {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
@media (max-width: 1024px) { .products { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 720px)  { .products { grid-template-columns: repeat(2, 1fr); gap: 16px; } }

.product {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .15s ease, box-shadow .15s ease;
  position: relative;
}
.product:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: #efe9dc;
  overflow: hidden;
}
.product-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.product:hover .product-media img { transform: scale(1.04); }

.product-badges {
  position: absolute;
  top: 10px; left: 10px;
  display: flex; flex-direction: column; gap: 6px;
}
.badge-pill {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--surface);
  color: var(--ink);
  border: 1px solid var(--line);
}
.badge-pill.sale { background: var(--sale); color: #fff; border-color: var(--sale); }
.badge-pill.new  { background: var(--ink); color: #fff; border-color: var(--ink); }

.wishlist-btn {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--surface);
  display: grid; place-items: center;
  cursor: pointer;
  color: var(--ink);
}
.wishlist-btn[aria-pressed="true"] { background: var(--ink); color: #fff; border-color: var(--ink); }
.wishlist-btn:hover { border-color: var(--ink); }

.product-body {
  padding: 16px;
  display: flex; flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: .75rem;
  color: var(--muted);
  letter-spacing: .04em;
  text-transform: uppercase;
}
.product-title {
  font-weight: 600;
  font-size: 1rem;
  margin: 0;
}
.product-title a { text-decoration: none; }
.product-title a:hover { text-decoration: underline; }

.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: .8125rem;
  color: var(--muted);
}
.stars {
  position: relative;
  display: inline-block;
  color: #d6cfc1;
  font-size: 0.95rem;
  letter-spacing: 1px;
}
.stars-fill {
  position: absolute;
  top: 0; left: 0;
  overflow: hidden;
  white-space: nowrap;
  color: #c2410c;
}

.product-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: auto;
  padding-top: 4px;
}
.price-now { font-weight: 700; font-size: 1.0625rem; color: var(--ink); }
.price-was { color: var(--muted); text-decoration: line-through; font-size: .875rem; }
.price-off { color: var(--sale); font-weight: 700; font-size: .8125rem; }

.product-actions {
  display: flex; gap: 8px;
  padding: 0 16px 16px;
}
.add-to-cart {
  flex: 1;
  appearance: none;
  cursor: pointer;
  border: 1px solid var(--ink);
  background: var(--surface);
  color: var(--ink);
  padding: 10px 12px;
  border-radius: 8px;
  font-weight: 600;
  font-size: .875rem;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.add-to-cart:hover { background: var(--ink); color: #fff; }
.add-to-cart.added { background: var(--ok); color: #fff; border-color: var(--ok); }

/* ---------- Deals (featured + tiles) ---------- */
.deals {
  background: var(--surface);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 24px;
}
@media (max-width: 880px) { .deals-grid { grid-template-columns: 1fr; } }

.deal-hero {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  min-height: 380px;
  background: #1f1a16 center/cover no-repeat;
  color: #fff;
  display: flex;
  align-items: end;
}
.deal-hero::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,.05) 0%, rgba(0,0,0,.65) 100%);
}
.deal-hero-body {
  position: relative;
  z-index: 1;
  padding: 32px;
  max-width: 480px;
}
.deal-hero h3 {
  font-family: var(--serif);
  font-weight: 600;
  font-size: clamp(1.5rem, 2.6vw, 2rem);
  margin: 12px 0 8px;
}
.deal-hero p { margin: 0 0 20px; color: #f1ede6; }

.countdown {
  display: flex; gap: 8px;
  margin-bottom: 20px;
}
.countdown-cell {
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 8px;
  padding: 8px 12px;
  min-width: 56px;
  text-align: center;
  backdrop-filter: blur(6px);
}
.countdown-cell strong {
  display: block;
  font-family: var(--serif);
  font-size: 1.4rem;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.countdown-cell span {
  font-size: .7rem;
  color: #e8e1d0;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.deal-tiles {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
@media (max-width: 540px) { .deal-tiles { grid-template-columns: 1fr; } }

.deal-tile {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  padding: 24px;
  text-decoration: none;
  color: var(--ink);
  background: #f4efe6;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 180px;
  overflow: hidden;
  transition: transform .15s ease;
}
.deal-tile:hover { transform: translateY(-2px); }
.deal-tile.tile-2 { background: #e8e2d2; }
.deal-tile.tile-3 { background: #1f1a16; color: #fff; }
.deal-tile.tile-4 { background: #d9cfbb; }
.deal-tile h4 {
  font-family: var(--serif);
  font-size: 1.25rem;
  margin: 8px 0 4px;
}
.deal-tile small { opacity: .8; font-size: .8125rem; }
.deal-tile .arrow {
  align-self: flex-start;
  margin-top: 16px;
  font-weight: 600;
  font-size: .875rem;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
@media (max-width: 880px) { .editorial-grid { grid-template-columns: 1fr; } }

.editorial-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
  transition: transform .15s ease, box-shadow .15s ease;
}
.editorial-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.editorial-media {
  aspect-ratio: 16 / 10;
  background: #efe9dc;
  overflow: hidden;
}
.editorial-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
.editorial-card:hover .editorial-media img { transform: scale(1.04); }
.editorial-body { padding: 20px 22px 24px; }
.editorial-tag {
  font-size: .75rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 700;
}
.editorial-card h3 {
  font-family: var(--serif);
  font-size: 1.375rem;
  margin: 8px 0 8px;
  font-weight: 600;
  line-height: 1.25;
}
.editorial-card p { color: var(--muted); margin: 0 0 16px; font-size: .9375rem; }
.editorial-meta {
  display: flex; gap: 12px;
  align-items: center;
  font-size: .8125rem;
  color: var(--muted);
}

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--ink);
  color: #fff;
}
.newsletter-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 48px;
  align-items: center;
}
@media (max-width: 880px) { .newsletter-grid { grid-template-columns: 1fr; gap: 24px; } }
.newsletter h2 {
  font-family: var(--serif);
  font-size: clamp(1.75rem, 3vw, 2.25rem);
  margin: 8px 0 8px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.newsletter p { color: #e8e1d0; max-width: 48ch; margin: 0 0 8px; }
.newsletter form {
  display: flex;
  gap: 8px;
  align-items: stretch;
  flex-wrap: wrap;
}
.field {
  display: flex; flex-direction: column;
  flex: 1;
  min-width: 0;
}
.field label {
  font-size: .8125rem;
  margin-bottom: 6px;
  color: #e8e1d0;
}
.field .required { color: #fbbf24; margin-left: 2px; }
.newsletter input[type="email"] {
  appearance: none;
  border: 1px solid #3a3530;
  background: #1f1a16;
  color: #fff;
  padding: 12px 14px;
  border-radius: 8px;
  font-family: inherit;
  font-size: 1rem;
  min-height: 48px;
  width: 100%;
}
.newsletter input[type="email"]:focus-visible { outline-color: #fbbf24; }
.newsletter input[aria-invalid="true"] { border-color: #fca5a5; }
.field .help, .field .error {
  font-size: .8125rem;
  margin-top: 6px;
  color: #c8c1b1;
}
.field .error { color: #fca5a5; }

.newsletter button {
  align-self: end;
  background: #fbbf24;
  color: var(--ink);
  border: 1px solid #fbbf24;
  padding: 12px 20px;
  border-radius: 8px;
  font-family: inherit;
  font-weight: 700;
  cursor: pointer;
  min-height: 48px;
}
.newsletter button:hover { background: #f59e0b; border-color: #f59e0b; }

.newsletter-status {
  margin-top: 12px;
  font-size: .9375rem;
}
.newsletter-status.ok { color: #86efac; }

/* ---------- Footer ---------- */
.site-footer {
  background: #f1ede6;
  border-top: 1px solid var(--line);
  padding: 56px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 40px;
}
@media (max-width: 880px) { .footer-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 540px) { .footer-grid { grid-template-columns: 1fr; } }

.footer-grid h4 {
  font-size: .8125rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  margin: 0 0 12px;
  color: var(--ink);
}
.footer-grid ul {
  list-style: none;
  padding: 0; margin: 0;
  display: grid;
  gap: 8px;
}
.footer-grid a {
  text-decoration: none;
  color: var(--ink-2);
}
.footer-grid a:hover { color: var(--ink); text-decoration: underline; }
.footer-brand p { color: var(--muted); max-width: 36ch; margin: 12px 0 16px; }
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid var(--line);
  display: grid; place-items: center;
  background: var(--surface);
}
.socials a:hover { border-color: var(--ink); }

.footer-bottom {
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  font-size: .8125rem;
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast-region {
  position: fixed;
  bottom: 24px; right: 24px;
  display: flex; flex-direction: column; gap: 8px;
  z-index: 100;
  pointer-events: none;
}
.toast {
  background: var(--ink);
  color: #fff;
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: var(--shadow-md);
  font-size: .9375rem;
  pointer-events: auto;
  display: flex; align-items: center; gap: 10px;
  animation: toast-in .2s ease-out;
}
@keyframes toast-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
  }
}

/* ---------- Forced colors ---------- */
@media (forced-colors: active) {
  .btn, .add-to-cart, .icon-btn, .wishlist-btn, .cat-card, .product, .editorial-card, .deal-tile {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .add-to-cart:hover { background: ButtonText; color: ButtonFace; }
  .badge-pill, .countdown-cell { border: 1px solid ButtonBorder; }
  .stars-fill { color: Highlight; }
  a:focus-visible, button:focus-visible, input:focus-visible {
    outline: 3px solid Highlight;
  }
}

