+}
+.deal-hero-body {
+  position: relative;
+  z-index: 1;
+  padding: 32px;
+  max-width: 480px;
+}
+.deal-hero h3 {
+  font-family: var(--serif);
+  font-weight: 600;
+  font-size: clamp(1.5rem, 2.6vw, 2rem);
+  margin: 12px 0 8px;
+}
+.deal-hero p { margin: 0 0 20px; color: #f1ede6; }
+
+.countdown {
+  display: flex; gap: 8px;
+  margin-bottom: 20px;
+}
+.countdown-cell {
+  background: rgba(255,255,255,.12);
+  border: 1px solid rgba(255,255,255,.2);
