+.deal-tile.tile-3 { background: #1f1a16; color: #fff; }
+.deal-tile.tile-4 { background: #d9cfbb; }
+.deal-tile h4 {
+  font-family: var(--serif);
+  font-size: 1.25rem;
+  margin: 8px 0 4px;
+}
+.deal-tile small { opacity: .8; font-size: .8125rem; }
+.deal-tile .arrow {
+  align-self: flex-start;
+  margin-top: 16px;
+  font-weight: 600;
+  font-size: .875rem;
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+}
+
+/* ---------- Editorial ---------- */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 24px;
+}
+@media (max-width: 880px) { .editorial-grid { grid-template-columns: 1fr; } }
+
+.editorial-card {
+  background: var(--surface);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  text-decoration: none;
+  color: inherit;
+  transition: transform .15s ease, box-shadow .15s ease;
