const Newsletter = () => {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState(null); // {type:'ok'|'error', msg}
  const [touched, setTouched] = useState(false);
  const inputRef = useRef(null);

  const validate = (v) => {
    if (!v) return "Please enter your email address.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) return "Please enter a valid email address (e.g. you@example.com).";
    return null;
  };
  const error = touched ? validate(email) : null;

  const handleSubmit = (ev) => {
    ev.preventDefault();
    setTouched(true);
    const err = validate(email);
    if (err) {
      setStatus({ type: "error", msg: err });
      inputRef.current && inputRef.current.focus();
      return;
    }
    setStatus({ type: "ok", msg: "Thanks! Check your inbox to confirm — we sent a welcome offer." });
    setEmail("");
    setTouched(false);
  };

  return e("section", { className: "newsletter", "aria-labelledby": "nl-title" },
    e("div", { className: "container newsletter-grid" },
      e("div", null,
        e("span", { className: "eyebrow", style: { background: "rgba(255,255,255,.1)", color: "#fff" } }, "Newsletter"),
