            ref: inputRef,
            "aria-required": "true",
            "aria-invalid": error ? "true" : "false",
            "aria-describedby": error ? "nl-error" : "nl-help",
            onChange: (ev) => { setEmail(ev.target.value); if (status) setStatus(null); },
            onBlur: () => setTouched(true)
          }),
          error
            ? e("span", { className: "error", id: "nl-error" }, error)
            : e("span", { className: "help", id: "nl-help" }, "We'll send a welcome code within minutes.")
        ),
        e("button", { type: "submit" }, "Subscribe"),
        e("div", {
          id: "nl-status",
          className: `newsletter-status ${status && status.type === "ok" ? "ok" : ""}`,
          "aria-live": "polite",
          style: { width: "100%" }
        }, status && status.type === "ok" ? status.msg : "")
