const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(new Set());
  const [justAdded, setJustAdded] = useState(null);
  const [toasts, setToasts] = useState([]);
  const toastIdRef = useRef(0);

  const pushToast = useCallback((msg) => {
    const id = ++toastIdRef.current;
    setToasts(t => [...t, { id, msg }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 2600);
  }, []);

  const handleAdd = useCallback((product) => {
    setCart(c => [...c, product.id]);
    setJustAdded(product.id);
    pushToast(`Added "${product.name}" to bag`);
    setTimeout(() => setJustAdded(prev => prev === product.id ? null : prev), 1400);
  }, [pushToast]);

  const handleWish = useCallback((id) => {
    setWishlist(w => {
      const next = new Set(w);
      if (next.has(id)) { next.delete(id); pushToast("Removed from wishlist"); }
      else { next.add(id); pushToast("Saved to wishlist"); }
      return next;
    });
  }, [pushToast]);

  return e(Fragment, null,
    e("a", { className: "skip-link", href: "#main" }, "Skip to main content"),
    e(AnnouncementBar),
    e(Header, { cartCount: cart.length, wishlistCount: wishlist.size }),
    e("main", { id: "main" },
      e(Hero),
      e(Categories),
      e(Featured, { onAdd: handleAdd, onWish: handleWish, wishlist, justAdded }),
      e(Deals),
      e(Editorial),
      e(Newsletter)
    ),
    e(Footer),
    e("div", { className: "toast-region", role: "status", "aria-live": "polite", "aria-atomic": "false" },
      toasts.map(t => e("div", { key: t.id, className: "toast" },
        e(Icon, { name: "check", size: 16 }),
        e("span", null, t.msg)
      ))
    )
  );
};

