const { useState, useEffect, useMemo, useRef, useCallback, Fragment } = React;
const e = React.createElement;

/* ============= Icons (inline SVG) ============= */
const Icon = ({ name, size = 20, label }) => {
  const common = {
    width: size, height: size, viewBox: "0 0 24 24",
    fill: "none", stroke: "currentColor", strokeWidth: 1.8,
    strokeLinecap: "round", strokeLinejoin: "round",
    "aria-hidden": label ? undefined : "true",
    role: label ? "img" : undefined,
    focusable: "false"
  };
  const paths = {
    search: e("circle", { cx: 11, cy: 11, r: 7 }),
    searchLine: e("path", { d: "M21 21l-4.3-4.3" }),
    user: [e("circle", { key: "c", cx: 12, cy: 8, r: 4 }), e("path", { key: "p", d: "M4 21c1.5-4 5-6 8-6s6.5 2 8 6" })],
    heart: e("path", { d: "M12 21s-7-4.35-9.5-9C1 8.5 3 5 6.5 5 9 5 10.5 6.5 12 8c1.5-1.5 3-3 5.5-3C21 5 23 8.5 21.5 12 19 16.65 12 21 12 21z" }),
    bag: [
      e("path", { key: "p", d: "M5 8h14l-1 12H6L5 8z" }),
      e("path", { key: "p2", d: "M9 8V6a3 3 0 0 1 6 0v2" })
    ],
    arrow: e("path", { d: "M5 12h14M13 6l6 6-6 6" }),
    check: e("path", { d: "M5 12l5 5 9-11" }),
    truck: [
      e("path", { key: "p", d: "M3 7h11v9H3z" }),
      e("path", { key: "p2", d: "M14 10h4l3 3v3h-7" }),
      e("circle", { key: "c1", cx: 7, cy: 18, r: 2 }),
      e("circle", { key: "c2", cx: 17, cy: 18, r: 2 })
    ],
    leaf: e("path", { d: "M5 19c0-9 7-14 16-14-1 9-6 16-14 16-2 0-2-2-2-2z M5 19c1-3 4-6 7-7" }),
    star: e("polygon", { points: "12 2 15 9 22 9.5 17 14.5 18.5 22 12 18 5.5 22 7 14.5 2 9.5 9 9 12 2" }),
    shield: e("path", { d: "M12 3l8 3v6c0 5-3.5 8.5-8 9-4.5-.5-8-4-8-9V6l8-3z" }),
    spark: e("path", { d: "M12 3v6M12 15v6M3 12h6M15 12h6M6 6l4 4M14 14l4 4M6 18l4-4M14 10l4-4" }),
    shirt: e("path", { d: "M4 7l4-3h8l4 3-3 3v10H7V10L4 7z" }),
    shoe: e("path", { d: "M3 16c0-2 1-4 3-4 3 0 4 3 7 3l5-1c2-.3 3 .7 3 2v2H3v-2z" }),
    bag2: [
      e("path", { key: "p", d: "M4 8h16v12H4z" }),
      e("path", { key: "p2", d: "M9 8V5h6v3" })
    ],
    watch: [
      e("circle", { key: "c", cx: 12, cy: 12, r: 5 }),
      e("path", { key: "p", d: "M9 7l1-3h4l1 3M9 17l1 3h4l1-3" })
    ],
    home: e("path", { d: "M4 11l8-7 8 7v9h-5v-6h-6v6H4z" }),
    sparkles: e("path", { d: "M5 4l1 3 3 1-3 1-1 3-1-3-3-1 3-1 1-3zM17 11l1.5 4 4 1.5-4 1.5L17 22l-1.5-4-4-1.5 4-1.5L17 11z" }),
    facebook: e("path", { d: "M14 9h3V6h-3a3 3 0 0 0-3 3v2H8v3h3v7h3v-7h3l1-3h-4V9z" }),
    instagram: [
      e("rect", { key: "r", x: 3, y: 3, width: 18, height: 18, rx: 5 }),
      e("circle", { key: "c", cx: 12, cy: 12, r: 4 }),
      e("circle", { key: "d", cx: 17.5, cy: 6.5, r: 1, fill: "currentColor" })
    ],
    tiktok: e("path", { d: "M14 4v9.5a3.5 3.5 0 1 1-3.5-3.5h.5V13a1.5 1.5 0 1 0 1.5 1.5V4h2c.5 1.7 1.8 3 3.5 3.5V10c-1.3-.2-2.6-.7-4-1.6V4z" }),
    youtube: [
      e("path", { key: "p", d: "M2 8c0-2 1-3 3-3h14c2 0 3 1 3 3v8c0 2-1 3-3 3H5c-2 0-3-1-3-3V8z" }),
      e("path", { key: "t", d: "M10 9l5 3-5 3V9z", fill: "currentColor" })
    ]
  };
  const content = paths[name] || null;
  return e("svg", { ...common, "aria-label": label }, content);
};

/* ============= Data ============= */
const categories = [
