const products = [
  { id: "p1", name: "Linen Field Overshirt", category: "Apparel", price: 128, was: null, rating: 4.7, reviews: 312, badge: "new", img: "https://images.unsplash.com/photo-1562157873-818bc0726f68?auto=format&fit=crop&w=600&q=70" },
  { id: "p2", name: "Studio Tote in Saddle", category: "Bags", price: 184, was: 240, rating: 4.9, reviews: 158, badge: "sale", img: "https://images.unsplash.com/photo-1548036328-c9fa89d128fa?auto=format&fit=crop&w=600&q=70" },
