  { id: "p6", name: "Pilot Sunglasses — Tortoise", category: "Accessories", price: 145, was: null, rating: 4.7, reviews: 189, badge: null, img: "https://images.unsplash.com/photo-1572635196237-14b3f281503f?auto=format&fit=crop&w=600&q=70" },
  { id: "p7", name: "Wide-Leg Tailored Trouser", category: "Apparel", price: 138, was: 175, rating: 4.4, reviews: 145, badge: "sale", img: "https://images.unsplash.com/photo-1594633312681-425c7b97ccd1?auto=format&fit=crop&w=600&q=70" },
  { id: "p8", name: "Canvas Weekend Duffle", category: "Bags", price: 210, was: null, rating: 4.8, reviews: 233, badge: null, img: "https://images.unsplash.com/photo-1547949003-9792a18a2601?auto=format&fit=crop&w=600&q=70" }
];

const dealTiles = [
  { id: "d1", title: "Up to 40% off Outerwear", small: "Limited stock", cls: "tile-1" },
  { id: "d2", title: "Buy 2, Get 1 — Tees", small: "Mix & match", cls: "tile-2" },
  { id: "d3", title: "Members get 15% extra", small: "Sign in to unlock", cls: "tile-3" },
  { id: "d4", title: "Free shipping over $75", small: "U.S. orders", cls: "tile-4" }
