const editorial = [
  { id: "e1", tag: "Lookbook", title: "Soft Structures: Tailoring for the in-between season", excerpt: "Five ways our atelier is reworking the classics for everyday movement.", time: "6 min read", date: "Apr 28", img: "https://images.unsplash.com/photo-1558769132-cb1aea458c5e?auto=format&fit=crop&w=900&q=70" },
  { id: "e2", tag: "Inside Maison", title: "From loom to label: visiting our linen partners in Portugal", excerpt: "A decade-long partnership rooted in slow textiles and family craft.", time: "8 min read", date: "Apr 18", img: "https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=900&q=70" },
  { id: "e3", tag: "Field Notes", title: "How to care for your knits so they outlive trends", excerpt: "Simple rituals — from washing to storing — for a longer wardrobe.", time: "4 min read", date: "Apr 09", img: "https://images.unsplash.com/photo-1434389677669-e08b4cac3105?auto=format&fit=crop&w=900&q=70" }
];

/* ============= Components ============= */

const AnnouncementBar = () => e(
  "div", { className: "announce", role: "region", "aria-label": "Announcements" },
  e("span", null, "Free carbon-neutral shipping on orders over "),
  e("strong", null, "$75"),
  e("span", null, " · Members get 15% extra at checkout")
