const Header = ({ cartCount, wishlistCount }) => e(
  "header", { className: "site-header" },
  e("div", { className: "container header-row" },
    e("a", { className: "brand", href: "#", "aria-label": "Maison Cove — home" },
      e("span", { className: "brand-mark", "aria-hidden": "true" }, "M"),
      e("span", null, "Maison Cove")
    ),
    e("nav", { className: "primary-nav", "aria-label": "Primary" },
      e("ul", null,
        e("li", null, e("a", { href: "#new" }, "New In")),
        e("li", null, e("a", { href: "#women" }, "Women")),
        e("li", null, e("a", { href: "#men" }, "Men")),
        e("li", null, e("a", { href: "#home" }, "Home")),
        e("li", null, e("a", { href: "#sale" }, "Sale")),
        e("li", null, e("a", { href: "#journal" }, "Journal"))
      )
    ),
    e("div", { className: "header-actions" },
      e("button", { className: "icon-btn", type: "button", "aria-label": "Search" },
        e("svg", { width: 20, height: 20, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.8, strokeLinecap: "round", "aria-hidden": "true" },
          e("circle", { cx: 11, cy: 11, r: 7 }),
          e("path", { d: "M21 21l-4.3-4.3" })
        )
      ),
      e("button", { className: "icon-btn", type: "button", "aria-label": "Account" },
        e(Icon, { name: "user" })
      ),
      e("button", { className: "icon-btn", type: "button", "aria-label": `Wishlist, ${wishlistCount} items` },
        e(Icon, { name: "heart" }),
        wishlistCount > 0 && e("span", { className: "badge", "aria-hidden": "true" }, wishlistCount)
      ),
      e("button", { className: "icon-btn", type: "button", "aria-label": `Shopping bag, ${cartCount} items` },
        e(Icon, { name: "bag" }),
        cartCount > 0 && e("span", { className: "badge", "aria-hidden": "true" }, cartCount)
      )
    )
  )
);

const Hero = () => e(
  "section", { className: "hero", "aria-labelledby": "hero-title" },
  e("div", { className: "container hero-grid" },
    e("div", null,
      e("span", { className: "eyebrow" }, e(Icon, { name: "spark", size: 14 }), "Spring 2026 Collection"),
      e("h1", { id: "hero-title" }, "Quiet essentials, ", e("br"), "made to last beyond the season."),
      e("p", null, "Considered cuts, natural fibers, and small-batch production from ateliers we've worked with for over a decade."),
      e("div", { className: "hero-cta" },
        e("a", { className: "btn btn-primary", href: "#featured" }, "Shop the collection ", e(Icon, { name: "arrow", size: 16 })),
        e("a", { className: "btn btn-secondary", href: "#journal" }, "Read the lookbook")
      ),
      e("div", { className: "hero-meta" },
        e("div", null, e(Icon, { name: "truck", size: 18 }), e("span", null, "Free shipping over $75")),
        e("div", null, e(Icon, { name: "leaf", size: 18 }), e("span", null, "Carbon-neutral delivery")),
        e("div", null, e(Icon, { name: "shield", size: 18 }), e("span", null, "30-day returns"))
      )
    ),
    e("figure", { className: "hero-figure" },
      e("img", {
        src: "https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=900&q=75",
        alt: "Model wearing a beige linen overshirt and tailored trousers, photographed in soft natural light."
      }),
      e("div", { className: "hero-tag" },
        e("strong", null, "The Field Overshirt"),
        e("span", null, "From $128 · 3 colorways")
      )
    )
  )
);

const Categories = () => e(
  "section", { className: "categories", "aria-labelledby": "cat-title" },
  e("div", { className: "container" },
    e("h2", { id: "cat-title", className: "sr-only", style: { position: "absolute", left: -10000 } }, "Shop by category"),
    e("ul", null,
      categories.map(c => e("li", { key: c.id },
        e("a", { className: "cat-card", href: `#${c.id}` },
          e("span", { className: "cat-icon", "aria-hidden": "true" }, e(Icon, { name: c.icon, size: 22 })),
          e("span", { className: "cat-name" }, c.name),
          e("span", { className: "cat-count" }, `${c.count} items`)
        )
      ))
    )
  )
);

const Stars = ({ value }) => {
  const pct = Math.round((value / 5) * 100);
  return e("span", { className: "stars", "aria-hidden": "true" },
    "★★★★★",
    e("span", { className: "stars-fill", style: { width: pct + "%" } }, "★★★★★")
  );
};

const ProductCard = ({ product, onAdd, onWish, wished, justAdded }) => e(
  "article", { className: "product", "aria-labelledby": `pt-${product.id}` },
  e("div", { className: "product-media" },
    e("img", { src: product.img, alt: `${product.name} — product photo`, loading: "lazy" }),
    product.badge && e("div", { className: "product-badges" },
      e("span", { className: `badge-pill ${product.badge}` }, product.badge === "sale" ? "Sale" : "New")
    ),
    e("button", {
      className: "wishlist-btn",
      type: "button",
      "aria-pressed": wished ? "true" : "false",
      "aria-label": `${wished ? "Remove from" : "Add to"} wishlist: ${product.name}`,
      onClick: () => onWish(product.id)
    }, e(Icon, { name: "heart", size: 18 }))
  ),
  e("div", { className: "product-body" },
    e("span", { className: "product-cat" }, product.category),
    e("h3", { className: "product-title", id: `pt-${product.id}` },
      e("a", { href: `#product-${product.id}` }, product.name)
    ),
    e("div", { className: "product-rating" },
      e(Stars, { value: product.rating }),
      e("span", null, `${product.rating.toFixed(1)} (${product.reviews})`)
    ),
    e("div", { className: "product-price" },
      e("span", { className: "price-now" },
        e("span", { className: "sr-only", style: { position: "absolute", left: -10000 } }, "Price: "),
        `$${product.price}`
      ),
      product.was && e(Fragment, null,
        e("span", { className: "price-was", "aria-label": `Was $${product.was}` }, `$${product.was}`),
        e("span", { className: "price-off" }, `−${Math.round((1 - product.price / product.was) * 100)}%`)
      )
    )
  ),
  e("div", { className: "product-actions" },
    e("button", {
      className: `add-to-cart ${justAdded ? "added" : ""}`,
      type: "button",
      onClick: () => onAdd(product),
      "aria-label": `Add to bag: ${product.name}, $${product.price}`
    },
      e(Icon, { name: justAdded ? "check" : "bag", size: 16 }),
      e("span", null, justAdded ? "Added" : "Add to bag")
