    e("div", { className: "section-head" },
      e("div", null,
        e("span", { className: "eyebrow" }, "Hand-picked"),
        e("h2", { id: "feat-title" }, "Featured this week")
      ),
      e("div", { className: "head-actions" },
        e("a", { className: "btn btn-ghost", href: "#all" }, "View all ", e(Icon, { name: "arrow", size: 16 }))
      )
    ),
    e("div", { className: "products" },
      products.map(p => e(ProductCard, {
        key: p.id, product: p,
        onAdd, onWish,
        wished: wishlist.has(p.id),
        justAdded: justAdded === p.id
      }))
    )
  )
);

const Countdown = () => {
  // Target: ~2 days, 13 hours from page load
  const targetRef = useRef(Date.now() + (2 * 24 + 13) * 3600 * 1000);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  let diff = Math.max(0, targetRef.current - now);
  const d = Math.floor(diff / 86400000); diff -= d * 86400000;
  const h = Math.floor(diff / 3600000);  diff -= h * 3600000;
  const m = Math.floor(diff / 60000);    diff -= m * 60000;
  const s = Math.floor(diff / 1000);
  const pad = n => String(n).padStart(2, "0");
  return e("div", {
    className: "countdown",
    role: "timer",
    "aria-label": `Sale ends in ${d} days, ${h} hours, ${m} minutes`
  },
    [["Days", d], ["Hrs", h], ["Min", m], ["Sec", s]].map(([l, v]) =>
      e("div", { key: l, className: "countdown-cell" },
        e("strong", null, pad(v)),
        e("span", null, l)
      )
    )
  );
};

const Deals = () => e(
  "section", { className: "deals", id: "sale", "aria-labelledby": "deals-title" },
  e("div", { className: "container" },
    e("div", { className: "section-head" },
      e("div", null,
        e("span", { className: "eyebrow" }, "Limited time"),
        e("h2", { id: "deals-title" }, "Deals & member offers")
