    ),
    e("div", { className: "deals-grid" },
      e("article", {
        className: "deal-hero",
        style: { backgroundImage: "linear-gradient(180deg, rgba(0,0,0,.05), rgba(0,0,0,.5)), url(https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1200&q=70)" },
        "aria-labelledby": "deal-hero-title"
      },
        e("div", { className: "deal-hero-body" },
          e("span", { className: "eyebrow", style: { background: "rgba(255,255,255,.15)", color: "#fff" } }, "Spring Edit"),
          e("h3", { id: "deal-hero-title" }, "Up to 40% off select outerwear"),
          e("p", null, "Trench coats, parkas and quilted layers — only while sizes last."),
          e(Countdown),
          e("a", { className: "btn", href: "#shop-sale", style: { background: "#fff", color: "#14110f" } },
            "Shop the sale ", e(Icon, { name: "arrow", size: 16 })
          )
        )
      ),
      e("div", { className: "deal-tiles" },
        dealTiles.map(t => e("a", { key: t.id, href: "#", className: `deal-tile ${t.cls}` },
          e("small", null, t.small),
          e("h4", null, t.title),
          e("span", { className: "arrow" }, "Shop now ", e(Icon, { name: "arrow", size: 14 }))
        ))
      )
    )
  )
);

const Editorial = () => e(
  "section", { id: "journal", "aria-labelledby": "ed-title" },
  e("div", { className: "container" },
    e("div", { className: "section-head" },
      e("div", null,
        e("span", { className: "eyebrow" }, "The Journal"),
        e("h2", { id: "ed-title" }, "Stories from the studio"),
        e("p", null, "Process notes, lookbooks, and conversations from the people who make our pieces.")
