        ),
        e("div", { className: "editorial-body" },
          e("span", { className: "editorial-tag" }, item.tag),
          e("h3", { id: `e-${item.id}` }, item.title),
          e("p", null, item.excerpt),
          e("div", { className: "editorial-meta" },
            e("span", null, item.date),
            e("span", { "aria-hidden": "true" }, "·"),
            e("span", null, item.time)
          )
        )
      ))
    )
  )
