const Newsletter = () => {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState(null); // {type:'ok'|'error', msg}
  const [touched, setTouched] = useState(false);
  const inputRef = useRef(null);

  const validate = (v) => {
    if (!v) return "Please enter your email address.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) return "Please enter a valid email address (e.g. you@example.com).";
    return null;
  };
  const error = touched ? validate(email) : null;

  const handleSubmit = (ev) => {
    ev.preventDefault();
    setTouched(true);
    const err = validate(email);
    if (err) {
      setStatus({ type: "error", msg: err });
      inputRef.current && inputRef.current.focus();
      return;
    }
    setStatus({ type: "ok", msg: "Thanks! Check your inbox to confirm — we sent a welcome offer." });
    setEmail("");
    setTouched(false);
  };

  return e("section", { className: "newsletter", "aria-labelledby": "nl-title" },
    e("div", { className: "container newsletter-grid" },
      e("div", null,
        e("span", { className: "eyebrow", style: { background: "rgba(255,255,255,.1)", color: "#fff" } }, "Newsletter"),
        e("h2", { id: "nl-title" }, "Get first looks and 10% off your first order"),
        e("p", null, "One email a week, no spam. Unsubscribe anytime.")
      ),
      e("form", { onSubmit: handleSubmit, noValidate: true, "aria-describedby": "nl-status" },
        e("div", { className: "field" },
          e("label", { htmlFor: "nl-email" }, "Email address", e("span", { className: "required", "aria-hidden": "true" }, "*")),
          e("input", {
            id: "nl-email", type: "email", required: true,
            placeholder: "you@example.com",
            value: email,
            ref: inputRef,
            "aria-required": "true",
            "aria-invalid": error ? "true" : "false",
            "aria-describedby": error ? "nl-error" : "nl-help",
            onChange: (ev) => { setEmail(ev.target.value); if (status) setStatus(null); },
            onBlur: () => setTouched(true)
          }),
          error
            ? e("span", { className: "error", id: "nl-error" }, error)
            : e("span", { className: "help", id: "nl-help" }, "We'll send a welcome code within minutes.")
        ),
        e("button", { type: "submit" }, "Subscribe"),
        e("div", {
          id: "nl-status",
          className: `newsletter-status ${status && status.type === "ok" ? "ok" : ""}`,
          "aria-live": "polite",
          style: { width: "100%" }
        }, status && status.type === "ok" ? status.msg : "")
      )
    )
  );
};

